// Outer-structure probe #1: exact skeleton, byte-level, key order, path string.
import { execFileSync } from 'node:child_process';
const EXE = '/workspace/dataset/test1_executable';

function runBuf(a, b) {
  try {
    const out = execFileSync(EXE, ['--a', a, '--b', b], { stdio: ['ignore', 'pipe', 'pipe'] });
    return { buf: out, err: Buffer.alloc(0), code: 0 };
  } catch (e) {
    return { buf: e.stdout ?? Buffer.alloc(0), err: e.stderr ?? Buffer.alloc(0), code: e.status ?? -1 };
  }
}

const cases = [
  ['equal-empty', '', ''],
  ['equal-a', 'a', 'a'],
  ['equal-multiline', 'x\ny', 'x\ny'],
  ['simple-diff', 'a', 'b'],
  ['diffkey', 'a\nb', 'a\nc'],
  ['numlike-1', '1.0', '1.00'],
  ['numlike-2', '1e5', '100000'],
  ['numlike-3', '1', '1'],
  ['numlike-4', '1', '2'],
  ['bools', 'True', 'False'],
  ['none', 'None', 'null'],
  ['nan', 'nan', 'NaN'],
  ['inf', 'inf', '-inf'],
  ['inf2', 'Infinity', 'inf'],
  ['numeq', '01', '1'],
  ['numeq2', '1_000', '1000'],
  ['hex', '0x10', '16'],
  ['complexlike', '1j', '1'],
  ['listlike', '[1, 2]', '[1, 3]'],
  ['dictlike', "{'a': 1}", "{'a': 2}"],
  ['tuplelike', '(1, 2)', '(1, 3)'],
  ['bytelike', "b'abc'", "b'abd'"],
  ['datelike', '2020-01-01', '2020-01-02'],
  ['long-a', 'x'.repeat(500), 'y'.repeat(500)],
  ['spaces', '  ', ' '],
  ['quote-in-vals', "it's", "it's not"],
];

const out = [];
for (const [name, a, b] of cases) {
  const r = runBuf(a, b);
  out.push({
    name, a: JSON.stringify(a).slice(0, 60), b: JSON.stringify(b).slice(0, 60),
    code: r.code,
    len: r.buf.length,
    lastBytes: [...r.buf.subarray(Math.max(0, r.buf.length - 6))],
    text: JSON.stringify(r.buf.toString('utf8')).slice(0, 400),
    err: r.err.length ? JSON.stringify(r.err.toString('utf8')).slice(0, 200) : '',
  });
}
console.log(JSON.stringify(out, null, 1));

// Outer-structure probe #2: quoting independence of diff value; apostrophes in lines.
import { execFileSync } from 'node:child_process';
const EXE = '/workspace/dataset/test1_executable';
function run(a, b) {
  try {
    return { out: execFileSync(EXE, ['--a', a, '--b', b], { encoding: 'utf8', stdio: ['ignore','pipe','pipe'] }), code: 0 };
  } catch (e) { return { out: e.stdout ?? '', err: e.stderr ?? '', code: e.status ?? -1 }; }
}

const cases = [
  // apostrophe only in a -> old_value should use double quotes; diff contains it too
  ['apos-in-a', "it's\nfoo", "bar\nfoo"],
  // apostrophe only in b
  ['apos-in-b', "bar\nfoo", "it's\nfoo"],
  // apostrophe in both
  ['apos-both', "it's\nfoo", "it's not\nfoo"],
  // apostrophe in a line that is NOT part of diff output context? unified diff has context
  ['apos-context', "it's\nA", "it's\nB"],
  // apostrophe AND double quote in same string -> repr uses single quotes with \'
  ['both-quotes', "it's \"q\"\nA", "plain\nA"],
  // double quote only
  ['dq-only', '"q"\nA', 'p\nA'],
  // does diff value quoting differ from values? value has no quote, diff has quote
  // impossible? diff is built from lines of a and b. try where apostrophe only in b
  ['a-clean-b-apos', "A\nB", "A\nit's"],
  // backslash handling in diff
  ['backslash', 'a\\b\nX', 'c\nX'],
  // tab in lines
  ['tab', 'a\tb\nX', 'c\nX'],
  // non-ascii
  ['nonascii', 'é\nX', 'e\nX'],
  ['emoji', '😀\nX', 'x\nX'],
];
for (const [name, a, b] of cases) {
  const r = run(a, b);
  console.log(name, '|', JSON.stringify(a), '=>', JSON.stringify(b));
  console.log('   ', JSON.stringify(r.out));
