// Outer-structure probe #3: single-line invariant, huge diffs, normalization, stderr, newline count.
import { execFileSync } from 'node:child_process';
const EXE = '/workspace/dataset/test1_executable';
function run(a, b) {
  try {
    const out = execFileSync(EXE, ['--a', a, '--b', b], { stdio: ['ignore','pipe','pipe'] });
    return { out, err: Buffer.alloc(0), code: 0 };
  } catch (e) { return { out: e.stdout ?? Buffer.alloc(0), err: e.stderr ?? Buffer.alloc(0), code: e.status ?? -1 }; }
}

function report(name, a, b) {
  const r = run(a, b);
  const s = r.out.toString('utf8');
  const nlCount = (s.match(/\n/g) || []).length;
  const crCount = (s.match(/\r/g) || []).length;
  console.log(`### ${name}`);
  console.log(`  code=${r.code} bytes=${r.out.length} literalNL=${nlCount} literalCR=${crCount} endsWithNL=${s.endsWith('\n')} stderr=${JSON.stringify(r.err.toString('utf8')).slice(0,160)}`);
  console.log(`  out=${JSON.stringify(s).slice(0, 500)}`);
  // top-level key extraction
  const m = /^\{'([a-z_]+)':/.exec(s);
  console.log(`  topKey=${m ? m[1] : (s === '{}\n' ? '<empty>' : '<??>')}`);
  // innermost key order
  const keys = [...s.matchAll(/'(new_value|old_value|diff)':/g)].map(x => x[1]);
  console.log(`  innerKeyOrder=${JSON.stringify(keys)}`);
  console.log('');
}

// 1. Huge multiline diff -- does the printed repr stay on ONE line? any truncation?
const bigA = Array.from({length: 300}, (_, i) => 'line' + i).join('\n');
const bigB = Array.from({length: 300}, (_, i) => 'line' + (i % 7 === 0 ? 'X' + i : i)).join('\n');
report('300-line-diff', bigA, bigB);

// 2. very long single line, no newline
report('long-single-line', 'x'.repeat(3000), 'y'.repeat(3000));

// 3. unicode normalization NFC vs NFD (same visual char)
report('nfc-vs-nfd', 'é', 'é');
report('nfc-vs-nfd-multiline', 'é\nZ', 'é\nZ');

// 4. CRLF
report('crlf', 'a\r\nb', 'a\r\nc');
report('crlf-equal-after-splitlines', 'a\r\nb', 'a\nb');

// 5. case only
report('case-only', 'ABC', 'abc');

// 6. trailing space
report('trailing-space', 'a', 'a ');

// 7. numeric-looking equality checks
report('num-1-vs-1.0', '1', '1.0');
report('num-5-vs-5.', '5', '5.');
report('num-plus1-vs-1', '+1', '1');
report('num-1e2-vs-100.0', '1e2', '100.0');
report('num-0-vs-0.0', '0', '0.0');
report('num-0-vs-minus0', '0', '0');
report('nan-vs-nan', 'nan', 'nan');
report('true-vs-1', 'True', '1');
report('num-1_0-vs-10', '10', '1e1');
report('bignum', '9'.repeat(60), '9'.repeat(59) + '8');

// 8. empty vs empty and empty vs space
report('empty-vs-empty', '', '');
report('empty-vs-space', '', ' ');

// 9. equal multiline (no diff key even though newline present)
report('equal-multiline', 'p\nq\nr', 'p\nq\nr');

// Outer-structure probe #4: strict skeleton validation over many inputs + reconstruct check.
import { execFileSync } from 'node:child_process';
const EXE = '/workspace/dataset/test1_executable';
function run(a, b) {
  try { return { out: execFileSync(EXE, ['--a', a, '--b', b], { stdio:['ignore','pipe','pipe'] }), err: Buffer.alloc(0), code: 0 }; }
  catch (e) { return { out: e.stdout ?? Buffer.alloc(0), err: e.stderr ?? Buffer.alloc(0), code: e.status ?? -1 }; }
}

const PRE  = "{'values_changed': {'root': {'new_value': ";
const SEP  = ", 'old_value': ";
const SEP2 = ", 'diff': ";
const SUF  = "}}}\n";

// generate a varied corpus (avoiding literal '-' at string start -> argparse eats it)
const pieces = [
  'a', 'b', 'ab', 'A', 'z z', '  ', '\t', 'x\ny', 'x\ny\nz', 'p\n', '\np', '\n', '\n\n',
  "it's", '"dq"', "mix'\"", 'back\\slash', 'é', '😀', ' ', 'line1\nline2\nline3',
  'null', 'True', 'nan', '1', '1.0', '0x1f', '[1]', "{'k': 'v'}", 'root', 'values_changed',
  "{'values_changed': {'root': {'new_value': 'x', 'old_value': 'y'}}}",
  ", 'old_value': ", ", 'diff': ", '}}}', 'new_value',
  'a\rb', 'ab', 'a\fb', 'ab', 'ab', 'a b',
  'x'.repeat(200), 'q\n'.repeat(30),
];

let n = 0, fails = [], observed = new Set(), inner4 = [];
for (let i = 0; i < pieces.length; i++) {
  const a = pieces[i];
  const b = pieces[(i * 7 + 3) % pieces.length];
  const r = run(a, b);
  n++;
  const s = r.out.toString('utf8');
  if (r.code !== 0) { fails.push([a, b, 'EXITCODE ' + r.code, r.err.toString('utf8')]); continue; }
  if (a === b) {
    if (s !== '{}\n') fails.push([a, b, 'EQUAL-NOT-{}', JSON.stringify(s)]);
    observed.add('EMPTY');
    continue;
  }
  // structural checks
  if (!s.startsWith(PRE)) { fails.push([a, b, 'BAD-PREFIX', JSON.stringify(s.slice(0, 60))]); continue; }
  if (!s.endsWith(SUF)) { fails.push([a, b, 'BAD-SUFFIX', JSON.stringify(s.slice(-20))]); continue; }
  const nl = (s.match(/\n/g) || []).length;
  if (nl !== 1) fails.push([a, b, 'MULTI-LITERAL-NEWLINE ' + nl, '']);
  const body = s.slice(PRE.length, s.length - SUF.length);
  // topkey / order
  const topKeys = [...s.matchAll(/^\{'([a-z_]+)'/g)].map(x => x[1]);
  observed.add(topKeys[0]);
  const innerKeys = [...body.matchAll(/(?:^|, )'(new_value|old_value|diff)': /g)].map(x => x[1]);
  if (innerKeys.length > 3) inner4.push([a, b, JSON.stringify(s).slice(0,200)]);
  // reconstruct: split body on SEP (first occurrence that yields valid halves)
  const iSep = body.indexOf(SEP);
  if (iSep < 0) fails.push([a, b, 'NO-OLDVALUE-SEP', JSON.stringify(s).slice(0,200)]);
  // no trailing comma before }}}
  if (/,\s*$/.test(body)) fails.push([a, b, 'TRAILING-COMMA', JSON.stringify(body.slice(-10))]);
  // no space before closing braces
  if (/[ ]$/.test(body)) fails.push([a, b, 'TRAILING-SPACE-IN-BODY', JSON.stringify(body.slice(-10))]);
  if (r.err.length) fails.push([a, b, 'STDERR', r.err.toString('utf8').slice(0,120)]);
}
console.log('cases:', n);
console.log('top-level keys observed:', [...observed]);
console.log('inner dicts with >3 keys:', inner4.length, JSON.stringify(inner4).slice(0, 400));
console.log('failures:', fails.length);
for (const f of fails) console.log('  FAIL', JSON.stringify(f).slice(0, 300));

// Outer-structure probe #5: byte-exact template assertions, encoding, large inputs.
import { execFileSync } from 'node:child_process';
const EXE = '/workspace/dataset/test1_executable';
function run(a, b, env) {
  try { return { out: execFileSync(EXE, ['--a', a, '--b', b], { stdio:['ignore','pipe','pipe'], env: env ?? process.env }), err: Buffer.alloc(0), code: 0 }; }
  catch (e) { return { out: e.stdout ?? Buffer.alloc(0), err: e.stderr ?? Buffer.alloc(0), code: e.status ?? -1 }; }
}

// ---- byte-exact assertions with hand-written expected literals ----
const asserts = [
  ['a', 'a', "{}\n"],
  ['', '', "{}\n"],
  ['a', 'b', "{'values_changed': {'root': {'new_value': 'b', 'old_value': 'a'}}}\n"],
  ['', 'b', "{'values_changed': {'root': {'new_value': 'b', 'old_value': ''}}}\n"],
  ['a\nb', 'a\nc',
    "{'values_changed': {'root': {'new_value': 'a\\nc', 'old_value': 'a\\nb', 'diff': '--- \\n+++ \\n@@ -1,2 +1,2 @@\\n a\\n-b\\n+c'}}}\n"],
  ['\n', '', "{'values_changed': {'root': {'new_value': '', 'old_value': '\\n', 'diff': '--- \\n+++ \\n@@ -1 +0,0 @@\\n-'}}}\n"],
  ["it's", 'b', "{'values_changed': {'root': {'new_value': 'b', 'old_value': \"it's\"}}}\n"],
];
let bad = 0;
for (const [a, b, exp] of asserts) {
  const got = run(a, b).out.toString('utf8');
  const ok = got === exp;
  if (!ok) bad++;
  console.log((ok ? 'OK  ' : 'MISMATCH ') + JSON.stringify([a, b]));
  if (!ok) { console.log('   exp=' + JSON.stringify(exp)); console.log('   got=' + JSON.stringify(got)); }
}
console.log('byte-exact mismatches:', bad, '\n');

// ---- encoding: is non-ascii emitted as raw UTF-8? ----
const r = run('é😀', 'x');
console.log('nonascii bytes:', r.out.toString('hex'));
console.log('nonascii utf8 :', JSON.stringify(r.out.toString('utf8')));
console.log('roundtrip-ok  :', r.out.toString('utf8').includes('é😀'), '\n');

// ---- large inputs: any truncation / limit / stderr warning? ----
for (const nLines of [500, 2000]) {
  const A = Array.from({length: nLines}, (_, i) => 'l' + i).join('\n');
  const B = Array.from({length: nLines}, (_, i) => (i % 3 ? 'l' + i : 'L' + i)).join('\n');
  const t0 = Date.now();
  const rr = run(A, B);
