  console.log(`lines=${nLines} code=${rr.code} bytes=${rr.out.length} ms=${Date.now()-t0} literalNL=${(s.match(/\n/g)||[]).length} hasDiffKey=${s.includes("'diff': ")} stderr=${JSON.stringify(rr.err.toString('utf8')).slice(0,200)}`);
  console.log('   tail=' + JSON.stringify(s.slice(-80)));
}

// ---- huge single line (argv limit sanity) ----
const big = 'x'.repeat(60000);
const rb = run(big, big.slice(0, 59999) + 'y');
console.log(`bigline code=${rb.code} bytes=${rb.out.length} literalNL=${(rb.out.toString('utf8').match(/\n/g)||[]).length} prefixOK=${rb.out.toString('utf8').startsWith("{'values_changed': {'root': {'new_value': '")} stderr=${JSON.stringify(rb.err.toString('utf8')).slice(0,150)}`);

// Outer-structure probe #6: quote-aware parse of the skeleton + full byte reconstruct for 2-key case.
import { execFileSync } from 'node:child_process';
const EXE = '/workspace/dataset/test1_executable';
function run(a, b) {
  try { return { out: execFileSync(EXE, ['--a', a, '--b', b], { stdio:['ignore','pipe','pipe'] }), err: Buffer.alloc(0), code: 0 }; }
  catch (e) { return { out: e.stdout ?? Buffer.alloc(0), err: e.stderr ?? Buffer.alloc(0), code: e.status ?? -1 }; }
}
const PRE = "{'values_changed': {'root': {'new_value': ", SEP = ", 'old_value': ", SEP2 = ", 'diff': ", SUF = "}}}\n";

// minimal python str repr for corpus chars (ASCII printable + \n \r \t + latin letters)
function pyRepr(s) {
  const q = (s.includes("'") && !s.includes('"')) ? '"' : "'";
  let o = q;
  for (const ch of s) {
    if (ch === '\\') o += '\\\\';
    else if (ch === q) o += '\\' + q;
    else if (ch === '\n') o += '\\n';
    else if (ch === '\r') o += '\\r';
    else if (ch === '\t') o += '\\t';
    else {
      const c = ch.codePointAt(0);
      if (c < 0x20 || c === 0x7f) o += '\\x' + c.toString(16).padStart(2, '0');
      else o += ch;
    }
  }
  return o + q;
}
// parse a python single/double quoted literal at index i; returns {value, end}
function parseLit(s, i) {
  const q = s[i];
  if (q !== "'" && q !== '"') return null;
  let v = '', j = i + 1;
  while (j < s.length) {
    const c = s[j];
    if (c === '\\') {
      const n = s[j + 1];
      if (n === 'n') { v += '\n'; j += 2; }
      else if (n === 'r') { v += '\r'; j += 2; }
      else if (n === 't') { v += '\t'; j += 2; }
      else if (n === '\\') { v += '\\'; j += 2; }
      else if (n === "'" || n === '"') { v += n; j += 2; }
      else if (n === 'x') { v += String.fromCharCode(parseInt(s.substr(j + 2, 2), 16)); j += 4; }
      else if (n === 'u') { v += String.fromCharCode(parseInt(s.substr(j + 2, 4), 16)); j += 6; }
      else if (n === 'U') { v += String.fromCodePoint(parseInt(s.substr(j + 2, 8), 16)); j += 10; }
      else { v += c; j += 1; }
    } else if (c === q) { return { value: v, end: j + 1 }; }
    else { v += c; j += 1; }
  }
  return null;
}

const corpus = [
  'a', 'b', 'hello world', "don't", '"q"', `mix'"`, 'sl\\ash', 'tab\there', 'cr\rhere',
  'nl\nhere', 'nl\nhere\nmore', 'one\n', '\nlead', '\n\n\n', 'é', 'ünïcode', '😀 face',
  '', ' ', '   ', '1', '1.0', 'True', 'None', 'root', 'new_value', 'old_value', 'diff',
  "', 'old_value': '", "'}}}", 'x'.repeat(120), 'a\nb\nc\nd\ne',
  "it's\na\"b", 'q\\\nw', 'zzz', 'ZZZ', 'a b\tc\nd', 'foo', 'bar',
];

let structFail = [], reconFail = [], roundFail = [], nDiff = 0, nPlain = 0, nEmpty = 0;
for (let i = 0; i < corpus.length; i++) {
  const a = corpus[i], b = corpus[(i * 13 + 5) % corpus.length];
  const r = run(a, b);
  const s = r.out.toString('utf8');
  if (r.code !== 0) { structFail.push([a, b, 'exit ' + r.code, r.err.toString('utf8')]); continue; }
  if (a === b) { if (s !== '{}\n') structFail.push([a, b, 'equal not {}', s]); nEmpty++; continue; }
  if (!s.startsWith(PRE)) { structFail.push([a, b, 'prefix', s.slice(0, 50)]); continue; }
  let p = parseLit(s, PRE.length);
  if (!p) { structFail.push([a, b, 'new_value literal unparsable', s.slice(0, 80)]); continue; }
  if (p.value !== b) roundFail.push([a, b, 'new_value decoded != b', JSON.stringify(p.value)]);
  if (s.slice(p.end, p.end + SEP.length) !== SEP) { structFail.push([a, b, 'sep1', JSON.stringify(s.slice(p.end, p.end + 20))]); continue; }
  let q = parseLit(s, p.end + SEP.length);
  if (!q) { structFail.push([a, b, 'old_value literal unparsable', s.slice(0, 80)]); continue; }
  if (q.value !== a) roundFail.push([a, b, 'old_value decoded != a', JSON.stringify(q.value)]);
  let rest = s.slice(q.end);
  if (rest === SUF) {
    nPlain++;
    // full byte reconstruct using our pyRepr
    const exp = PRE + pyRepr(b) + SEP + pyRepr(a) + SUF;
    if (exp !== s) reconFail.push([a, b, JSON.stringify(exp).slice(0,150), JSON.stringify(s).slice(0,150)]);
  } else if (rest.startsWith(SEP2)) {
    nDiff++;
    const d = parseLit(s, q.end + SEP2.length);
    if (!d) { structFail.push([a, b, 'diff literal unparsable', JSON.stringify(rest).slice(0,120)]); continue; }
    if (s.slice(d.end) !== SUF) structFail.push([a, b, 'suffix after diff', JSON.stringify(s.slice(d.end))]);
    if (d.value.includes('\n') === false) structFail.push([a, b, 'diff has no real newline after decode', JSON.stringify(d.value)]);
    // check the diff repr's own quote choice is independent
    const dq = s[q.end + SEP2.length];
    const expQ = (d.value.includes("'") && !d.value.includes('"')) ? '"' : "'";
    if (dq !== expQ) structFail.push([a, b, 'diff quote choice', dq + ' expected ' + expQ]);
  } else {
    structFail.push([a, b, 'unexpected tail', JSON.stringify(rest).slice(0, 120)]);
  }
  if (r.err.length) structFail.push([a, b, 'stderr', r.err.toString('utf8').slice(0, 100)]);
}
console.log(`cases=${corpus.length} empty=${nEmpty} twoKey=${nPlain} threeKey=${nDiff}`);
console.log('structFail=' + structFail.length); structFail.forEach(f => console.log('  S', JSON.stringify(f).slice(0,300)));
console.log('roundFail=' + roundFail.length);  roundFail.forEach(f => console.log('  R', JSON.stringify(f).slice(0,300)));
console.log('reconFail=' + reconFail.length);  reconFail.forEach(f => console.log('  C', JSON.stringify(f).slice(0,400)));

// swapped argv order must not change output
const x = run('a\nb', 'a\nc').out.toString('utf8');
let y;
try { y = execFileSync(EXE, ['--b', 'a\nc', '--a', 'a\nb'], { stdio:['ignore','pipe','pipe'] }).toString('utf8'); } catch (e) { y = 'ERR'; }
console.log('argv-order-invariant:', x === y);

// Outer-structure probe #7: hunt for a non-'values_changed' top key / non-'root' path.
import { execFileSync } from 'node:child_process';
const EXE = '/workspace/dataset/test1_executable';
function run(a, b) {
  try { return { out: execFileSync(EXE, ['--a', a, '--b', b], { encoding:'utf8', stdio:['ignore','pipe','pipe'] }), err:'', code: 0 }; }
  catch (e) { return { out: e.stdout ?? '', err: e.stderr ?? '', code: e.status ?? -1 }; }
}
const pairs = [
  // substring / iterable-ish
  ['abc', 'abcd'], ['ab', 'ba'], ['abcd', 'abc'], ['aaa', 'aa'],
  // number sniffing
  ['1', '01'], ['1', '1 '], [' 1', '1'], ['1.5', '1.50'], ['2', '2.0'],
  ['1e309', 'inf'], ['1E5', '1e5'], ['0b101', '5'], ['1/2', '0.5'],
  ['12345678901234567890', '12345678901234567891'],
  ['1,000', '1000'], ['$1', '1'],
